NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'I Thessalonians'

CHAPTERS = {
    1: {
        1: 'Paulus, Silvanus und Timotheus an die Gemeinde der Thessalonicher in Gott dem Vater und dem Herrn Jesus Christus: Gnade sei mit euch und Friede von Gott unserem Vater und dem Herrn Jesus Christus!',
        2: 'Wir danken Gott allezeit für euch alle, indem wir euer in unseren Gebeten ohne Unterlaß gedenken,',
        3: 'Eingedenk eures Werkes im Glauben, und eurer Arbeit in der Liebe, und eurer Beharrlichkeit in der Hoffnung auf unseren Herrn Jesus Christus vor Gott, unserem Vater;',
        4: 'Weil wir wissen, von Gott geliebte Brüder, eure Erwählung,',
        5: 'Daß unser Evangelium bei euch nicht allein im Wort, sondern auch in der Kraft und im Heiligen Geist und in großer Zuversicht besteht, wie ihr selbst wißt, wie wir uns unter euch zu eurem Besten erwiesen haben.',
        6: 'Und ihr seid unsere und des Herrn Nacheiferer geworden und habt das Wort unter vieler Trübsal mit Freude des Heiligen Geistes aufgenommen;',
        7: 'Also, daß ihr allen Gläubigen in Mazedonien und Achaja Vorbilder geworden seid.',
        8: 'Denn von euch ist das Wort des Herrn erschollen, nicht allein in Mazedonien und in Achaja, sondern euer Glaube an Gott ist auch allerorten ausgekommen, so daß wir nicht nötig haben, etwas davon zu sagen.',
        9: 'Denn sie selbst verkündigen von uns, welchen Eingang wir bei euch hatten, und wie ihr euch von den Abgöttern zu Gott bekehrt habt, um dem lebendigen und wahren Gott zu dienen;',
        10: 'Und Seinen Sohn, Den Er von den Toten auferweckt, Jesus, Der uns von dem zukünftigen Zorn errettet, aus dem Himmel zu erwarten.',
    },
    2: {
        1: 'Ihr wißt ja selbst, Brüder, daß unser Auftreten bei euch nicht vergeblich gewesen ist.',
        2: 'Wie wir, obwohl wir zuvor in Philippi Leiden und Schmach, wie ihr wißt, erduldet hatten, dennoch im Vertrauen auf unseren Gott unter vielem Kampfe euch das Evangelium freimütig verkündigt haben.',
        3: 'Denn unsere Ermahnung kommt nicht aus Irrwahn, Unlauterkeit oder Arglist;',
        4: 'Sondern wie wir von Gott bewährt erfunden wurden, daß uns das Evangelium anvertraut wurde, also reden wir nicht als solche, die Menschen, sondern Gott gefallen wollen, Der unsere Herzen prüft.',
        5: 'Denn wir sind, wie ihr wißt, nie mit Schmeichelworten umgegangen, noch hatten wir habsüchtige Absichten, Gott ist unser Zeuge.',
        6: 'Auch haben wir nicht Ehre bei Menschen gesucht, weder bei euch, noch bei anderen,',
        7: 'Wir hätten als Christi Apostel uns bei euch ein Gewicht geben können, allein wir blieben anspruchslos und benahmen uns in eurer Mitte, wie eine Amme ihre Kindlein pflegt;',
        8: 'Also hatten wir unsere Lust an euch, und es machte uns Freude, euch nicht nur das Evangelium Gottes mitzuteilen, sondern auch unser Leben hinzugeben, weil wir euch liebgewonnen hatten.',
        9: 'Denn ihr erinnert euch, Brüder, noch wohl unserer Mühe und Beschwerde, wie wir Tag und Nacht arbeiteten, um keinem von euch beschwerlich zu fallen, und euch das Evangelium Gottes verkündeten.',
        10: 'Ihr seid Zeugen und Gott, wie heilig, gerecht und unsträflich wir vor euch, die ihr glaubtet, gewesen sind.',
        11: 'Wie ihr denn wißt, daß wir einen jeglichen unter euch, wie ein Vater seine Kinder, ermahnt und ermuntert,',
        12: 'Und beschworen haben, zu wandeln würdig Gottes, Der euch in Sein Reich und Seine Herrlichkeit berufen hat.',
        13: 'Weshalb wir auch ohne Unterlaß Gott danken, daß ihr das Wort der Predigt von Gott von uns empfangen und nicht als Menschenwort aufgenommen habt, sondern so wie es wirklich ist, als Wort Gottes, welches auch in euch, die ihr glaubt, sich wirksam erweist.',
        14: 'Denn ihr, Brüder, seid Nacheiferer der Gemeinden Gottes Judäas in Jesus Christus geworden, weil auch ihr gleiches von euren Volksgenossen erlitten habt, wie auch sie von den Juden,',
        15: 'Die sogar den Herrn Jesus und ihre eigenen Propheten getötet und uns verfolgt haben, und Gott mißfällig und aller Menschen Feinde sind;',
        16: 'Die uns wehren, zu den Heiden zu sprechen, daß diese selig werden, so daß sie das Maß ihrer Sünden voll machen; aber der Zorn Gottes ist endlich über sie gekommen.',
        17: 'Wir aber, Brüder, die wir auf eine Zeitlang euer beraubt waren, von Angesicht, nicht dem Herzen nach, sehnten uns um so mehr mit großem Verlangen, euer Angesicht wiederzusehen.',
        18: 'Darum wollten wir',
        19: 'Denn wer ist die Hoffnung, oder Freude, oder Krone unseres Rühmens, so nicht auch ihr es seid, vor unserem Herrn Jesus Christus bei Seiner Wiederkunft?',
        20: 'Ja, ihr seid unsere Herrlichkeit und Freude.',
    },
    3: {
        1: 'Darum konnten wir es nicht länger ertragen und wollten lieber allein in Athen bleiben;',
        2: 'Und haben Timotheus, unseren Bruder und Mitarbeiter Gottes im Evangelium Christi, gesandt, daß er euch stärke und ermahne in Ansehung eures Glaubens.',
        3: 'Damit niemand wanke in diesen Bedrängnissen; ihr wißt ja selbst, daß wir dazu bestimmt sind.',
        4: 'Und als wir bei euch waren, sagten wir es euch ja voraus, daß wir würden in Trübsal kommen, wie es denn geschah und euch bekannt ist.',
        5: 'Darum konnte ich es nicht länger ertragen, und schickte ihn ab, auf daß ich erführe, wie es mit eurem Glauben steht, ob nicht etwa der Versucher euch versucht habe und unsere Arbeit vereitelt wäre.',
        6: 'Nun aber, da Timotheus von euch zu uns gekommen und uns über euren Glauben und eure Liebe frohe Botschaft brachte, und daß ihr uns immer noch in gutem Andenken habt, und Verlangen tragt, uns zu sehen, wie denn auch uns verlangt, euch zu sehen;',
        7: 'Da sind wir denn über euch, Brüder, bei aller unserer Trübsal und Not durch euren Glauben getröstet worden.',
        8: 'Denn nun leben wir auf, weil ihr im Herrn beständig seid.',
        9: 'Denn wie können wir Gott genug danken für all die Freude, die wir euretwegen vor unserem Gott empfinden!',
        10: 'Tag und Nacht bitten wir angelegentlichst, daß wir euer Angesicht sehen dürften, um das, was noch mangelt an eurem Glauben, voll zu machen.',
        11: 'Er Selbst aber, unser Gott und Vater und unser Herr Jesus Christus bahne unseren Weg zu euch.',
        12: 'Euch aber lasse der Herr zunehmen und überschwenglich werden in der Liebe zueinander und gegen jedermann wie denn auch wir gegen euch gesinnt sind.',
        13: 'Daß Er eure Herzen stärke und ihr unsträflich seid in der Heiligkeit vor Gott und unserem Vater, auf die Zukunft unseres Herrn Jesus Christus mit allen Seinen Heiligen.',
    },
    4: {
        1: 'Weiter denn bitten und ermahnen wir euch, Brüder, in dem Herrn, daß ihr, gleich wie ihr von uns empfangen habt, wie ihr sollt wandeln und Gott gefallen, darin immer völliger werdet.',
        2: 'Ihr wißt ja, welche Vorschriften wir euch durch den Herrn Jesus gegeben haben.',
        3: 'Denn dies ist der Wille Gottes, eure Heiligung, daß ihr euch der Hurerei enthaltet,',
        4: 'Und ein jeglicher von euch wisse, sein Gefäß in Zucht und Ehren zu erhalten.',
        5: 'Nicht in Leidenschaft der Begierde wie die Heiden, die von Gott nichts wissen.',
        6: 'Und daß keiner übergreife und seinen Bruder im Handel übervorteile; denn der Herr ist Rächer über alles dies, wie wir euch auch vorher gesagt und bezeugt haben.',
        7: 'Denn Gott hat uns nicht zur Unreinheit, sondern zur Heiligung berufen.',
        8: 'Wer daher dies verwirft, der verwirft nicht Menschen, sondern Gott, Der Seinen Heiligen Geist in uns gegeben hat.',
        9: 'Über brüderliche Liebe brauche ich euch nicht zu schreiben; denn ihr seid von Gott Selbst gelehrt, einander zu lieben.',
        10: 'Und das tut ihr ja auch an allen Brüdern in ganz Mazedonien; wir ermahnen euch aber, Brüder, daß ihr immer noch völliger werdet;',
        11: 'Und euch beeifert, ruhig zu bleiben, das eurige zu tun, und mit euren eigenen Händen zu arbeiten, wie wir euch anempfohlen haben;',
        12: 'Auf daß ihr ehrbarlich wandelt vor denen, die draußen sind, und niemandes bedürft.',
        13: 'Wir wollen euch aber, Brüder, nicht in Unkunde lassen über die, so da entschlafen, auf daß ihr euch nicht betrübt, wie die anderen, die keine Hoffnung haben.',
        14: 'Denn wie wir glauben, daß Jesus Christus gestorben und auferstanden ist, also wird auch Gott die Entschlafenen durch Jesus Christus zu Sich nehmen.',
        15: 'Denn soviel sagen wir mit dem Worte des Herrn, daß wir, die Lebenden, die überbleiben bis zur Wiederkunft des Herrn, den Entschlafenen nicht zuvorkommen werden.',
        16: 'Denn Er Selbst, der Herr, wird mit einem gegebenen Losungsruf und der Stimme des Erzengels und der Posaune Gottes vom Himmel herniederkommen, und die Toten in Christus werden zuerst auferstehen.',
        17: 'Danach wir, die wir leben und überbleiben, werden zugleich mit denselben in den Wolken in die Luft dem Herrn entgegengerückt werden, und so werden wir dann allezeit bei dem Herrn sein.',
        18: 'So tröstet euch nun mit diesen Worten untereinander!',
    },
    5: {
        1: 'Über Zeit und Zeitumstände, Brüder, ist nicht Not, euch zu schreiben;',
        2: 'Ihr wißt ja selbst genau, daß der Tag des Herrn kommen wird wie ein Dieb in der Nacht.',
        3: 'Denn wenn sie sagen: Es ist Friede, ist keine Gefahr, so steht plötzlich das Verderben vor der Tür, wie die Wehen vor dem Weib, das gebären soll; und sie können nicht entfliehen.',
        4: 'Ihr aber, Brüder, seid nicht in Finsternis, so daß euch der Tag wie der Dieb überfalle.',
        5: 'Ihr alle seid ja Kinder des Lichts und Kinder des Tags; wir sind nicht von der Nacht, noch von der Finsternis.',
        6: 'So laßt uns denn nicht schlafen, wie die anderen, sondern wachen und nüchtern sein.',
        7: 'Denn die da schlafen, schlafen in der Nacht, und die da trunken sind, sind trunken in der Nacht.',
        8: 'Wir aber, die wir vom Tage sind, wollen nüchtern sein, mit dem Panzer des Glaubens und der Liebe angetan, und mit dem Helm der Hoffnung zur Seligkeit.',
        9: 'Denn Gott hat uns nicht gesetzt zum Zorn, sondern zur Erlangung der Seligkeit durch unseren Herrn Jesus Christus, Der für uns gestorben ist.',
        10: 'Auf daß wir, ob wir wachen oder schlafen, zugleich mit Ihm leben sollen.',
        11: 'Darum ermahnt einander und erbaue einer den anderen, wie ihr denn auch tut.',
        12: 'Wir bitten euch aber, Brüder, daß ihr sorgt für die, welche an euch arbeiten und euch vorstehen in dem Herrn und euch vermahnen.',
        13: 'Und haltet sie hoch in eurer Liebe, um ihres Werkes willen. Haltet Frieden untereinander.',
        14: 'Wir ermahnen euch aber, liebe Brüder, weiset zurecht die Unordentlichen, tröstet die Kleinmütigen, nehmt euch der Schwachen an, seid langmütig gegen alle.',
        15: 'Seht darauf, daß keiner Böses mit Bösem vergelte, sondern jagt allezeit dem Guten nach, beides, untereinander und gegen jedermann.',
        16: 'Seid allezeit frohen Mutes.',
        17: 'Betet ohne Unterlaß.',
        18: 'Seid dankbar in allen Dingen, denn das ist der Wille Gottes in Christus Jesus an euch.',
        19: 'Den Geist dämpfet nicht.',
        20: 'Mißachtet nicht Weissagungen,',
        21: 'Sondern prüft alles, das Gute behaltet!',
        22: 'Meidet allen bösen Schein.',
        23: 'Er aber, der Gott des Friedens, heilige euch durch und durch, und Geist, Seele und Leib möge an euch völlig unsträflich erhalten werden für die Zukunft unseres Herrn Jesus Christus.',
        24: 'Treu ist Er, Der euch ruft, und wird es auch vollbringen.',
        25: 'Brüder, betet für uns!',
        26: 'Grüßet alle Brüder mit dem heiligen Kuß.',
        27: 'Ich beschwöre euch bei dem Herrn, daß ihr diesen Brief alle heiligen Brüder lesen lasset.',
        28: 'Die Gnade unseres Herrn Jesu Christi sei mit euch! Amen.',
    },
}
